def keel_tick(natives: Natives, device: int | None, cycle_id: SupportsIndex, health: SupportsIndex) -> int:
    """Call keel_tick after checking its integer arguments.

    One health-loop step: input sampling, heartbeat, arming progress and motor-lease renewal.
    """
    checked_cycle_id = check_u64("keel_tick", "cycle_id", cycle_id)
    checked_health = check_u32("keel_tick", "health", health)
    return int(natives["keel_tick"](device, checked_cycle_id, checked_health))


def keel_cycle(natives: Natives, device: int | None, in_: Any, out: Any) -> int:
    """Call keel_cycle.

    Tick, apply a motor command and read the state in one call.
    """
    return int(natives["keel_cycle"](device, in_, out))


